        outStream.Append( outS ); 
        outS.Pc.xy = position + sizeText * (quadPositionUV[i].xy + inputs[0].pointQuad.zw); 
        outS.Pc.y += textYbias; 
        outStream.Append( outS ); 
    } 
    outS.Pc.xy = position + sizeBackground * (quadPositionUV[0].xy + inputs[0].pointQuad.zw); 
    outStream.Append( outS ); 
    outS.Pc.xy = position + sizeText * (quadPositionUV[0].xy + inputs[0].pointQuad.zw); 
    outS.Pc.y += textYbias; 
    outStream.Append( outS ); 
    outStream.RestartStrip(); 
    [unroll] for( int i = 0; i < 4; ++i ) { 
        outS.Pc.xy = position + sizeText * (quadPositionUV[i].xy + inputs[0].pointQuad.zw); 
        outS.Pc.y += textYbias; 
        float2 uv = inputs[0].uvQuad.xy + inputs[0].uvQuad.zw * quadPositionUV[i].zw; 
        outS.uvQuad = float4( uv, 0.0f, 0.0f); 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}
